<script lang="ts">
 import {onMount} from 'svelte';import {api,message} from './workspace';import {describeMarkdown,renderMarkdown} from './markdown.mjs';import type {Draft} from './types';import SharePreviewFields from './SharePreviewFields.svelte';import ShareLinks from './ShareLinks.svelte';import ExperimentVisibility from './ExperimentVisibility.svelte';
 export let expanded=false;
 export let uploading=false;export let title='';
 export let document:Draft;export let initialTitle='';export let disabled=false;export let description='';export let image='/api/shares/default-photo.jpg';
 let responses:{id:string;kind:string;body:string;name:string;created_at:string}[]=[];
 let body='',url='',shareId='',sharedTitle='',sharedDescription='',published='',followers:{name:string}[]=[],busy=false,error='',initialized='';
 $: if(document&&initialized!==document.revision.document_id){initialized=document.revision.document_id;title=initialTitle||document.title;body=document.body_md;description=describeMarkdown(body)||'Explore a small experiment, follow the learning, and find a little company for your curiosity.';}
 onMount(()=>{void load();});
 $: changed=!!url&&published!==JSON.stringify({title,description,image,body});
 async function load(){try{const result=await api.call<{id:string;title:string;description:string;image:string;body:string;url:string;active:boolean;responses?:typeof responses;followers?:{name:string}[]}>('share_current',{id:document.revision.document_id});if(result){shareId=result.id;responses=result.responses||[];followers=result.followers||[];title=result.title;description=result.description;image=result.image;body=result.body;if(result.active){url=result.url;sharedTitle=title;sharedDescription=description;published=JSON.stringify({title,description,image,body});}}}catch(e){error=message(e);}}
 async function refreshResponses(){busy=true;error='';try{const result=await api.call<{responses?:typeof responses}>('share_current',{id:document.revision.document_id});responses=result?.responses||[];}catch(e){error=message(e);}finally{busy=false;}}
 async function publish(){busy=true;error='';try{const result=await api.call<{id:string;url:string}>('share_create',{}, {document_id:document.revision.document_id,title,description,image,body});if(!result)throw new Error('The share link was not created.');shareId=result.id;url=result.url;sharedTitle=title;sharedDescription=description;published=JSON.stringify({title,description,image,body});}catch(e){error=message(e);}finally{busy=false;}}
 async function revoke(){busy=true;error='';try{await api.call('share_revoke',{id:shareId},{});url='';}catch(e){error=message(e);}finally{busy=false;}}
</script>
<details class="share-editor panel" open={expanded||document.doc_type==='invitation'}><summary>Share this {document.doc_type==='invitation'?'invitation':'experiment'}</summary><p class="fine">Choose the photo, description, and text people can see. This link is public to anyone who receives it. Your private notebook and other journey notes stay private.</p>
 <fieldset disabled={busy||disabled}><label>Public title<input bind:value={title} maxlength="180"/></label><SharePreviewFields bind:description bind:image bind:uploading {title} disabled={busy||disabled}/><label>Text to share<textarea bind:value={body} rows="6" maxlength="100000"></textarea></label><details class="public-text-preview"><summary>Preview the public text</summary><div class="invitation-body">{@html renderMarkdown(body)}</div></details></fieldset>
 {#if error}<p class="alert" role="alert">{error}</p>{/if}<button type="button" class="button primary" on:click={publish} disabled={disabled||busy||uploading||!title.trim()||description.trim().length<20}>{busy?'Saving…':url?'Update public share':'Create public share link'}</button>
 {#if url}{#if changed}<p class="fine" role="status">Update public share to apply these changes to your link.</p>{/if}<ShareLinks {url} title={sharedTitle} description={sharedDescription} kind={document.doc_type}/><button type="button" class="text-button" disabled={busy} on:click={revoke}>Stop sharing this link</button><p class="fine">Updates may take time to appear in previews already cached by messaging apps.</p>{/if}
 {#if document.doc_type==='experiment'&&shareId}<section aria-label="Visitor responses"><div class="row between"><h3>Feedback, stories &amp; outcomes</h3><button type="button" class="text-button" disabled={busy} on:click={refreshResponses}>Refresh responses</button></div><p class="fine">Private responses from people affected by your experiment. These are visitor reports, not verified outcomes.</p>{#each responses as response (response.id)}<article class="panel"><span class="eyebrow">{response.kind==='outcome'?'REPORTED OUTCOME':response.kind.toUpperCase()}</span><h4>{response.name||'Anonymous visitor'}</h4><p class="fine">{response.created_at} UTC</p><p style="white-space:pre-wrap">{response.body}</p></article>{:else}<p class="fine">No responses yet. Anyone with your public link can share their experience without signing in.</p>{/each}</section>{/if}
 {#if followers.length}<h3>Requests to follow along</h3><ul>{#each followers as follower}<li>{follower.name}</li>{/each}</ul>{/if}{#if url}<button type="button" class="text-button" disabled={busy} on:click={load}>Refresh follow requests</button>{/if}
</details>

{#if document.doc_type==='experiment'}<ExperimentVisibility experimentId={document.revision.document_id}/>{/if}
